mapper.select:
select ifnull(max(version_no), 0)
from basket_division_roster_version
where division_id = #{divisionId}

mapper.insert:
insert into basket_division_roster_version (
    division_id, version_no, registration_mode, rule_version_id, status,
    is_current, active_unique_key, formal_count, candidate_count, excluded_count,
    allocation_fingerprint, locked_time, locked_by, create_time, update_time, is_delete
) values (
    #{divisionId}, #{versionNo}, #{registrationMode}, #{ruleVersionId}, #{status},
    #{isCurrent}, #{activeUniqueKey}, #{formalCount}, #{candidateCount}, #{excludedCount},
    #{allocationFingerprint}, #{lockedTime}, #{lockedBy}, #{createTime}, #{updateTime}, #{isDelete}
)
